// One playable room. Shelves, recipe book, tools and food share the same space.
const pantryItems=[['Flour','¼ cup'],['Sugar','¼ cup'],['Baking powder','½ tsp'],['Baking soda','¼ tsp'],['Salt','pinch'],['Cocoa','¼ cup'],['Chocolate chips','¼ cup'],['Cinnamon','tsp'],['Butter','¼ cup'],['Egg','egg'],['Milk','¼ cup'],['Vanilla','tsp'],['Lemon juice','tbsp'],['Honey','tbsp']];
function room(){return `<div class="room" aria-hidden="true"><div class="room-wall"></div><div class="room-window"><div class="sky"></div><i></i><b></b><span class="valance"></span><span class="drape drape-l"></span><span class="drape drape-r"></span><span class="sill"></span></div><div class="room-counter"></div><div class="cabinet c-left"><i></i></div><div class="cabinet c-right"><i></i></div><div class="hanging-tools"><span></span><i></i><b></b></div><div class="flour-cloth"></div><div class="room-vase"><i></i><b></b></div></div>`}
function openRecipe(){const r=state.r;return `<aside class="counter-book" tabindex="0" role="button" aria-label="Open recipe book. Activate to read it more closely."><span class="book-cover"></span><div class="book-spread"><div class="book-page left-page"><span class="hand-label">Buttercup’s recipe book</span><h2>${r.name}</h2><div class="book-illustration">${art(r,1,r.frost,true)}</div><p class="book-order"><b>${r.customer.split(' ')[0]}’s order</b>“${r.wish}”</p></div><div class="book-page right-page"><div class="recipe-columns">${[['Dry',r.dry],['Wet',r.wet]].map(([title,items])=>`<div><h3>${title} ingredients</h3>${items.map(([n,v,u])=>`<div class="recipe-line"><span>${n}</span><b>${quantity(n,v,u)}</b></div>`).join('')}</div>`).join('')}</div><p class="book-method">Whisk dry & set aside; whisk wet separately.<br>Pour dry into wet, then fold gently.<br>Pan: <b>${typeof panForRecipe==='function'?panForRecipe(r).name:'recipe pan'}</b>.<br>Bake at <b>${r.temp}°C</b> for <b>${r.time} minutes</b>.<br>Decorate, then serve with love.</p><span class="page-number">${recipes.indexOf(r)*2+2}</span></div></div><span class="book-ribbon"></span></aside>`}
function wallPantry(active=false){return `<div class="wall-pantry" aria-label="Kitchen ingredient shelves">${pantryItems.map(([n,u],i)=>`<div class="shelf-slot"><button class="shelf-ingredient" data-pantry="${i}" aria-label="Pick up ${n}" ${active?'':'tabindex="-1"'}>${ingredientArt(n)}<span>${n}</span></button></div>`).join('')}</div>`}
function instruction(){return ['Measure the dry ingredients into the pink bowl.','Whisk the dry ingredients, then set the bowl aside.','Use the blue bowl for your wet ingredients.','Whisk the wet ingredients until smooth.','Pour the dry mixture into the wet bowl.','Gently fold the two mixtures together.','Choose a pan, then drag and tilt the bowl to fill it.',state.baked?'Your bake is ready to decorate.':state.baking?'Watch the batter rise and turn golden.':'Set the oven and slide in your filled pan.','Pipe a ribbon of frosting and add your finishing touches!'][state.stage]}
addKitchen=function(){};
const stageMix=mixStage,stageBake=bakeStage,stageDecor=decorateStage;
render=function(){document.body.classList.add('in-kitchen');const s=state;app.innerHTML=`<div class="game-room stage-${s.stage===7?3:s.stage===8?4:s.stage===6?'pan':[1,3,5].includes(s.stage)?2:0} phase-${s.stage}">${room()}<div class="game-hud"><button class="game-back" id="changeOrder" aria-label="Choose another recipe">↶ Orders</button><span class="order-title">${s.r.name}</span><div class="progress-ribbon">${['Dry','Whisk','Wet','Whisk','Combine','Fold','Fill pan','Bake','Decorate'].map((n,i)=>`<span class="${i===s.stage?'current':i<s.stage?'complete':''}">${i<s.stage?'✓':i+1}<small>${n}</small></span>`).join('')}</div></div>${wallPantry(s.stage===0||s.stage===2)}<div class="instruction-ribbon" id="roomInstruction">${instruction()}</div>${openRecipe()}${[2,3].includes(s.stage)?`<div class="set-aside-bowl" aria-label="Dry mixture in the pink bowl, set aside">${mixtureBowl('dry',true)}<span>Dry mixture · set aside</span></div>`:''}<section class="counter-station" id="work" aria-label="Kitchen work counter"></section><div class="room-customer" aria-hidden="true">${animalArt(s.r.animal)}<span>${s.r.customer.split(' ')[0]} is waiting…</span></div></div>`;document.getElementById('changeOrder').onclick=book;const recipeBook=document.querySelector('.counter-book');recipeBook.onclick=()=>recipeBook.classList.toggle('book-zoomed');recipeBook.onkeydown=e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();recipeBook.click()}};if(s.stage===0||s.stage===2)ingredientStage();else if([1,3,5].includes(s.stage))mixtureMixStage();else if(s.stage===4)combineStage();else if(s.stage===6)panFillStage();else if(s.stage===7)stageBake();else counterDecorateStage();document.querySelectorAll('#work .kitchen-backdrop').forEach(e=>e.remove());document.getElementById('work').querySelectorAll(':scope > .eyebrow,:scope > h2,:scope > p:not(.subtle)').forEach(e=>e.classList.add('station-caption'));};
// Volume in teaspoons keeps one measuring tool consistent across the pantry.
const measureUnits = {'¼ cup':12,'¼ tsp':.25,'½ tsp':.5,tsp:1,tbsp:3,pinch:1/16,egg:9};
const sharedMeasures = [
  ['1 pinch',1/16],['¼ tsp',.25],['½ tsp',.5],['1 tsp',1],['1½ tsp',1.5],['2 tsp',2],['3 tsp',3],
  ['1 tbsp',3],['2 tbsp',6],['3 tbsp',9],['¼ cup',12],['½ cup',24],['¾ cup',36],
  ['1 cup',48],['1½ cups',72],['2 cups',96],['1 egg',9],['2 eggs',18],['3 eggs',27],['4 eggs',36]
];
function pantryTotal(n, amount, u) {
  if(!amount) return '0';
  if(Math.abs(amount*measureUnits[u]*16-Math.round(amount*measureUnits[u]*16))<.001){
    const volume=amount*measureUnits[u];
    if(u==='egg' && Number.isInteger(amount))return quantity(n,amount,u);
    if(u==='pinch' && amount<=3)return quantity(n,amount,u);
    if(u==='¼ cup' && Number.isInteger(amount))return quantity(n,amount,u);
    if(u==='tbsp' && Number.isInteger(amount))return quantity(n,amount,u);
    if(Number.isInteger(volume*4))return fraction(volume)+' tsp';
    return Math.round(volume*16)+' pinches';
  }
  return quantity(n,amount,u);
}
ingredientStage=function(){const s=state;s.measureIndex??=13;s.history??=[];s.stageErrors??=[];s.selectedPantry??=0;s.dryAmounts??={};s.wetAmounts??={};const bucket=s.stage===0?s.dryAmounts:s.wetAmounts;const selected=pantryItems[s.selectedPantry];document.getElementById('work').innerHTML=`<div class="counter-action"><div class="counter-bowl"><button class="drop-bowl" id="dropBowl" aria-label="Mixing bowl. Drop an ingredient here, or activate to add the selected ingredient.">${mixtureBowl(s.stage===0?'dry':'wet')}<span id="bowlHint">${s.stage===0?'Dry ingredients · pink bowl':'Wet ingredients · blue bowl'}</span></button></div><div class="measuring-tool"><svg viewBox="0 0 100 80" aria-hidden="true"><path d="M10 8h63v55q-30 18-63 0Z" fill="#edf4f1bb" stroke="#9aaba8" stroke-width="3"/><path d="M73 18h13q17 15 0 30H73" fill="none" stroke="#9aaba8" stroke-width="5"/><path d="M14 28h18M14 42h12M14 55h18" stroke="#ba9d88" stroke-width="2"/></svg><div><label for="measureAmount">Choose your measure</label><select id="measureAmount" aria-label="Measuring amount"></select><small id="amountAdded">Then tap or drag an ingredient</small></div></div><div class="toast counter-toast" id="pourNote" role="status">Your measure stays set between pours.</div><div class="counter-actions"><button class="game-button undo-button" id="undoPour">↶ Undo pour</button><button class="game-button next-button" id="next">${s.stage===0?'Whisk dry ingredients →':'Whisk wet ingredients →'}</button></div><details class="bowl-log"><summary>What’s in this bowl?</summary><div id="bowlContents"></div></details></div>`;
const bowl=document.getElementById('dropBowl'),select=document.getElementById('measureAmount');function refreshLog(){document.getElementById('bowlContents').innerHTML=pantryItems.filter(([n])=>(bucket[n]||0)>0).map(([n,u])=>`<span>${n}: ${pantryTotal(n,bucket[n],u)}</span>`).join('')||'<span>Your bowl is empty.</span>'}function pick(i){s.selectedPantry=i;const [n,u]=pantryItems[i];document.querySelectorAll('.shelf-ingredient').forEach(el=>el.classList.toggle('held',+el.dataset.pantry===i));}
select.innerHTML=sharedMeasures.map(([label],i)=>`<option value="${i}">${label}</option>`).join('');
select.value=s.measureIndex;
select.onchange=()=>{s.measureIndex=Number(select.value)};
refreshLog();
function add(i){if(s.pouring)return;pick(i);const [n,u]=pantryItems[i];
const [label,volume]=sharedMeasures[s.measureIndex];
if(label.includes('egg') && n!=='Egg'){
  document.getElementById('pourNote').textContent='Choose a cup, spoon, or pinch for '+n.toLowerCase()+'.';return;
}
const amount=volume/measureUnits[u];
s.pouring=true;animateIngredient(n,amount,u,()=>{if(state!==s)return;s.pouring=false;bucket[n]=(bucket[n]||0)+amount;s.amounts[n]=(s.amounts[n]||0)+amount;s.history.push({n,amount,stage:s.stage});const needed=s.r.dry.some(x=>x[0]===n)?0:s.r.wet.some(x=>x[0]===n)?1:null;const actual=s.stage===0?0:1;if(needed!==null&&needed!==actual)s.stageErrors.push({n,expected:needed,actual,phase:s.stage});document.getElementById('pourNote').textContent=(label.includes('egg')?label:label+' '+n.toLowerCase())+' added.';document.getElementById('amountAdded').textContent=pantryTotal(n,bucket[n],u)+' '+n.toLowerCase()+' in this bowl';bowl.querySelector('svg').outerHTML=mixtureBowl(s.stage===0?'dry':'wet');refreshLog()})}
document.querySelectorAll('[data-pantry]').forEach(el=>{const i=+el.dataset.pantry;el.addEventListener('pointerdown',()=>pick(i));el.onclick=()=>add(i);bindDrag(el,()=>ingredientArt(pantryItems[i][0]),(x,y)=>{const r=bowl.getBoundingClientRect();if(x>=r.left&&x<=r.right&&y>=r.top&&y<=r.bottom)add(i)},(x,y)=>{const r=bowl.getBoundingClientRect();bowl.classList.toggle('drop-ready',x>=r.left&&x<=r.right&&y>=r.top&&y<=r.bottom)})});bowl.onclick=()=>add(s.selectedPantry);document.getElementById('undoPour').onclick=()=>{const last=s.history.at(-1);if(!last||last.stage!==s.stage||s.pouring)return;s.history.pop();bucket[last.n]=Math.max(0,(bucket[last.n]||0)-last.amount);s.amounts[last.n]=Math.max(0,(s.amounts[last.n]||0)-last.amount);const index=s.stageErrors.findLastIndex(x=>x.n===last.n&&x.phase===last.stage);if(index>=0)s.stageErrors.splice(index,1);document.getElementById('pourNote').textContent='Last pour scooped back out.';bowl.querySelector('svg').outerHTML=mixtureBowl(s.stage===0?'dry':'wet');document.getElementById('amountAdded').textContent='Tap or drag your next ingredient';refreshLog()};document.getElementById('next').onclick=()=>{if(s.pouring)return;s.stage++;render()}};
// Recipe mistakes produce different, specific texture/flavor outcomes.
scoreBake=function(){const s=state,r=s.r,faults=[],all=[...r.dry,...r.wet],need=new Map(all.map(([n,v,u])=>[n,{v,u}]));function fault(p,title,text){faults.push({p,title,text})}const outcomes={Flour:['the batter could not hold its shape','the crumb turned dry and heavy'],Sugar:['the bake tasted less sweet than it should','the bake was too sweet and browned faster'],Butter:['the crumb was dry instead of tender','the bake felt greasy and heavy'],Egg:['the crumb was fragile and did not set well','the texture was heavy and eggy'],Milk:['the batter was too thick and the crumb was dry','the center was too wet'],Cocoa:['the chocolate flavor was faint','the cocoa made it bitter and dry'],Salt:['the flavors tasted a little flat','the bake tasted too salty'],Vanilla:['the vanilla flavor was missing','the vanilla overwhelmed the other flavors'],'Lemon juice':['the lemon flavor was faint','the extra acid made it too tart'],'Chocolate chips':['there were fewer chocolatey bites','the extra chips overwhelmed the dough'],'Baking powder':['the bake rose poorly and stayed dense','the bake rose unevenly with a bitter aftertaste'],'Baking soda':['the bake stayed dense instead of fluffy','the extra soda left a soapy, bitter taste']};
for(const [n,v,u]of all){const got=s.amounts[n]||0,ratio=got/v,error=Math.abs(1-ratio);if(error>.08){const penalty=Math.min(15,error*10),phrase=ratio<1?outcomes[n]?.[0]:outcomes[n]?.[1];fault(penalty,'Ingredient balance',`${n}: you added ${got?pantryTotal(n,got,u):"none"} instead of ${quantity(n,v,u)}, so ${phrase||'the flavor and texture were out of balance'}.`)}}
for(const [n,got]of Object.entries(s.amounts)){if(got>0&&!need.has(n)){const u=pantryItems.find(x=>x[0]===n)?.[1]||'tsp';let effect=n==='Cinnamon'?'a cinnamon flavor the recipe did not call for':n==='Lemon juice'?'an unexpected tart flavor':n==='Cocoa'?'an unintended chocolate flavor and a drier crumb':n==='Milk'?'extra moisture and a wetter center':n==='Honey'?'extra sweetness and stickiness':n==='Baking soda'||n==='Baking powder'?'an unnecessary bitter raising agent':'an unintended flavor and texture';fault(16,'Wrong ingredient',`You added ${quantity(n,got,u)} ${n.toLowerCase()}, which this recipe does not use; it introduced ${effect}.`)}}
const mixRatio=s.foldStirs??s.mix/r.mix;if(mixRatio<.85)fault(Math.min(25,(1-mixRatio)*25),'Mixing',`You folded about ${Math.round(mixRatio*Math.max(3,Math.round(r.mix/2)))} of the suggested ${Math.max(3,Math.round(r.mix/2))} turns, leaving flour streaks in the ${r.name.toLowerCase()}.`);if(mixRatio>1.15)fault(Math.min(25,(mixRatio-1)*25),'Mixing','You kept stirring after the batter was smooth, making the crumb tougher instead of tender.');
if(s.twoBowl){if(s.dryStirs<.85)fault((1-s.dryStirs)*10,'Dry mixing',`After about ${Math.round(s.dryStirs*3)} of 3 dry whisk turns, the flour and ${r.dry.find(([n])=>n.startsWith('Baking'))?.[0].toLowerCase()||'cocoa'} still formed pockets.`);if(s.wetStirs<.85)fault((1-s.wetStirs)*10,'Wet mixing',`You whisked the wet bowl for about ${Math.round(s.wetStirs*3)} of 3 turns, so the butter and egg left streaks in the ${r.name.toLowerCase()}.`);if(!s.combined)fault(30,'Combining bowls','The dry mixture never reached the wet bowl, so the batter was incomplete.')}
const time=s.bakeProgress,heat=time/r.time*Math.pow(s.temp/r.temp,2);if(s.temp!==r.temp&&Math.abs(s.temp-r.temp)>=10)fault(Math.min(18,Math.abs(s.temp-r.temp)*.4),'Oven temperature',`The oven was ${s.temp}°C instead of ${r.temp}°C, ${s.temp>r.temp?'browning the outside before the middle cooked':'slowing the rise and leaving a paler crust'}.`);if(time<r.time*.9)fault(Math.min(35,(1-time/r.time)*40),'Baking time',`You baked for ${fraction(time)} minutes instead of ${r.time}, so the center stayed underbaked.`);else if(time>r.time*1.1)fault(Math.min(35,(time/r.time-1)*40),'Baking time',`You baked for ${fraction(time)} minutes instead of ${r.time}, drying out the edges.`);else if(heat<.8||heat>1.2)fault(10,'Bake balance',heat<.8?'The low oven heat left a soft, unset center.':'The extra oven heat dried the crumb and darkened the edges.');const errors=s.stageErrors||[];if(errors.length){const n=errors[0].n;fault(4,'Order of mixing',`You added ${n.toLowerCase()} during the ${errors[0].actual===0?'dry':'wet'} step rather than the ${errors[0].expected===0?'dry':'wet'} step, making the ingredients harder to combine evenly.`)}faults.sort((a,b)=>b.p-a.p);const penalty=faults.reduce((t,x)=>t+x.p,0);return {penalty,quality:Math.max(0,1-penalty/100),notes:faults.map(x=>[x.title,x.text]),faults}};
shortFeedback=function(result,correctFrost,correctTop,r){const lines=result.notes.slice(0,1).map(x=>x[1]);if(!lines.length&&(!correctFrost||!correctTop)){const detail=!correctFrost&&!correctTop?`${r.frost.toLowerCase()} frosting and ${r.top.toLowerCase()}`:!correctFrost?`${r.frost.toLowerCase()} frosting`:`${r.top.toLowerCase()} on top`;const used=[...new Set(state.decor.map(x=>x.type))].map(x=>x.toLowerCase()).join(' and ');lines.push(!correctFrost?`You served ${state.frost?state.frost.toLowerCase()+' frosting':'no frosting'} instead of my requested ${detail}.`:`You added ${used||'no toppings'} instead of the ${r.top.toLowerCase()} I ordered.`)}if(!lines.length)return 'The '+r.name.toLowerCase()+' baked for '+r.time+' minutes at '+r.temp+'°C, and the '+r.frost.toLowerCase()+' and '+r.top.toLowerCase()+' match my order.';return lines.join(' ')};
const woodlandFinish=results;results=function(){document.body.classList.remove('in-kitchen');woodlandFinish();document.body.classList.add('at-service')};
