start=function(i){clearTimers();state={r:recipes[i],stage:0,amounts:{},dryAmounts:{},wetAmounts:{},dryStirs:0,wetStirs:0,foldStirs:0,twoBowl:true,panWorkflow:true,pan:null,panFill:0,panContents:[],icingPaths:[],combined:false,mix:0,temp:175,minutes:20,bakeProgress:0,baking:false,baked:false,frost:null,top:null,decor:[],stageErrors:[]};render()};
