function transferMixtures(s){if(s.combined)return false;s.originalDryAmounts={...s.dryAmounts};for(const [n,v]of Object.entries(s.dryAmounts))s.wetAmounts[n]=(s.wetAmounts[n]||0)+v;s.dryAmounts={};s.combined=true;return true}
function combineStage(){const s=state;document.getElementById('work').innerHTML=`<div class="combine-counter"><button id="dryMixture" class="dry-transfer-source" aria-label="Dry mixture bowl. Drag into the wet bowl or activate to pour.">${mixtureBowl('dry',true)}<span>Dry mixture</span></button><div id="wetMixture" class="wet-transfer-target" role="img" aria-label="Blue bowl of wet mixture">${mixtureBowl('wet',true)}<span>Wet mixture</span><div class="combine-flour">${Array.from({length:18},(_,i)=>`<i style="--i:${i};--x:${i*11%45-22}px;--delay:${i%6*.08}s"></i>`).join('')}</div></div></div><div class="toast" id="combineNote" role="status">Drag the pink dry bowl over the blue wet bowl.</div><button class="primary" id="next" ${s.combined?'':'disabled'}>Fold the batter together →</button><p class="subtle">Or tap the pink bowl to pour. No extra ingredients are added.</p>`;const source=document.getElementById('dryMixture'),target=document.getElementById('wetMixture');function pour(){if(s.combining||s.combined)return;s.combining=true;source.disabled=true;document.querySelector('.combine-counter').classList.add('combining');document.getElementById('combineNote').textContent='The dry mixture is pouring into the wet bowl…';setTimeout(()=>{if(state!==s)return;transferMixtures(s);s.combining=false;source.querySelector('svg').outerHTML=mixtureBowl('dry');target.querySelector('svg').outerHTML=mixtureBowl('wet',true);source.classList.add('empty-bowl');document.getElementById('combineNote').textContent='Both mixtures are in the blue bowl. Time to fold gently!';document.getElementById('next').disabled=false},1300)}source.onclick=pour;bindDrag(source,()=>mixtureBowl('dry',true),(x,y)=>{const r=target.getBoundingClientRect();if(x>=r.left&&x<=r.right&&y>=r.top&&y<=r.bottom)pour()},(x,y)=>{const r=target.getBoundingClientRect();target.classList.toggle('drop-ready',x>=r.left&&x<=r.right&&y>=r.top&&y<=r.bottom)});document.getElementById('next').onclick=()=>{if(!s.combined)return;s.stage=5;render()}}
